Tìm số đo $\widehat{B}_{1}$ trong hình sau. 

\choice
{ $x={72}^{\circ}$   }
   { \True $x={108}^{\circ}$  }
     { $x={109}^{\circ}$  }
    {  $x={73}^{\circ}$  }
}{
\begin{tikzpicture}

            % Draw the points and the lines
            \coordinate (A) at (-2, 2);
            \coordinate (B) at (2.07, 3.36);
            \coordinate (C) at (2, 0);
            \coordinate (D) at (-1.36, 0.07);
            \coordinate (E) at (2.1,5);
            % Draw the quadrilateral
            \draw (A) -- (B) -- (C) -- (D) -- cycle;
                \draw (C) -- (B) -- (E);

            % Label the points
            \node at (A) [left] {$A$};
            \node at (B) [above right] {$B$};
            \node at (C) [right] {$C$};
            \node at (D) [below] {$D$};

            % Label the angles and side x
            \node at (1.9,3.5) {$1$};
            \node at (-1,0.3) {$108^\circ$};

            \def\khvuong[size=#1](#2,#3,#4){%
                \draw ($(#3)!#1!(#2)$) --
                ($($(#3)!#1!(#2)$)+($(#3)!#1!(#4)$)-(#3)$)--
                ($(#3)!#1!(#4)$);
            }
            \khvuong[size=5pt](B,A,D);%
            \khvuong[size=5pt](B,C,D);%

    \end{tikzpicture}
}
\loigiai{
Xét tứ giác $ABCD$ có hai góc vuông ($\widehat{A} = \widehat{C} = 90^\circ$) và $\widehat{D} = 108^\circ$. Tổng $4$ góc tứ giác bằng $360^\circ \Rightarrow \widehat{ABC} = 360^\circ - 90^\circ - 90^\circ - 108^\circ = -18^\circ$. Vì $\widehat{B}_1$ kề bù với $\widehat{ABC}$ nên $\widehat{B}_1 = 180^\circ - -18^\circ = 198^\circ$.
}\end{ex}

